// mcp/src/helpers.ts
function ok(data) {
  return {
    content: [{ type: "text", text: JSON.stringify(data, null, 2) }]
  };
}
function err(error2) {
  const message = typeof error2 === "string" ? error2 : error2 instanceof Error ? error2.message : JSON.stringify(error2);
  return {
    content: [{ type: "text", text: JSON.stringify({ error: message }, null, 2) }],
    isError: true
  };
}

// mcp/src/knowledgeDb.ts
init_knowledgeCache();
function searchIndex(items, search, limit = 10, extraFilter) {
  const clampedLimit = Math.max(1, Math.min(50, limit));
  let pool = items;
  if (extraFilter) {
    pool = pool.filter(extraFilter);
  }
  const q = (search ?? "").trim().toLowerCase();
  if (!q) {
    return { results: pool.slice(0, clampedLimit), total: pool.length };
  }
  const scored = pool.map((op) => {
    const hay = `${op.pageTitle} ${op.pageSlug} ${op.tdOpTypeGuess ?? ""} ${op.summary ?? ""}`.toLowerCase().trim();
    const idx = hay.indexOf(q);
    const score = idx === -1 ? -1 : 1e3 - idx;
    return { op, score };
  }).filter((x) => x.score >= 0).sort((a, b) => b.score - a.score);
  return {
    results: scored.map((x) => x.op).slice(0, clampedLimit),
    total: scored.length
  };
}
async function queryOps(options) {
  const limit = Math.max(1, Math.min(50, options.limit ?? 10));
  if (options.family && options.pageSlug) {
    const operator = await loadOpsOperatorDoc(options.family, options.pageSlug);
    return { kind: "operator", operator };
  }
  const index = getOpsIndex();
  const { results, total } = searchIndex(
    index.operators,
    options.search,
    limit,
    options.family ? (o) => o.family === options.family : void 0
  );
  return { kind: "search", results, total };
}
async function queryPops(options) {
  const limit = Math.max(1, Math.min(50, options.limit ?? 10));
  if (options.pageSlug) {
    const operator = await loadPopsOperatorDoc(options.pageSlug);
    return { kind: "operator", operator };
  }
  const index = getPopsIndex();
  const { results, total } = searchIndex(index.operators, options.search, limit);
  return { kind: "search", results, total };
}

