  server.registerTool(
    "td_get_param_help",
    {
      title: "Get Parameter Help",
      description: "Look up the available parameters for a TouchDesigner operator type (e.g. 'noiseTOP') from the local knowledge base.",
      inputSchema: {
        type: external_exports.string().describe(
          "Operator type to look up (e.g. 'noiseTOP', 'constantCHOP', 'mergeSOP', 'textDAT')"
        )
      }
    },
    async ({ type }) => {
      try {
        const opType = type;
        const index = await loadOpsIndex();
        const ops = index.operators || [];
        const matching = ops.filter(
          (op) => op.tdOpTypeGuess?.toLowerCase() === opType.toLowerCase() || op.pageSlug?.toLowerCase() === opType.toLowerCase()
        );
        let popMatch = null;
        try {
          const popsIndex = await loadPopsIndex();
          const pops = popsIndex.operators || [];
          const popsMatches = pops.filter(
            (op) => op.tdOpTypeGuess?.toLowerCase() === opType.toLowerCase() || op.pageSlug?.toLowerCase() === opType.toLowerCase()
          );
          if (popsMatches.length > 0) {
            popMatch = popsMatches[0];
          }
        } catch {
          const popCandidates = ops.filter(
            (op) => op.pageSlug?.toUpperCase().includes("POP") && (op.tdOpTypeGuess?.toLowerCase() === opType.toLowerCase() || op.pageSlug?.toLowerCase() === opType.toLowerCase())
          );
          if (popCandidates.length > 0) {
            popMatch = popCandidates[0];
          }
        }
        if (matching.length === 0 && !popMatch) {
          return ok({
            found: false,
            type: opType,
            message: `No operator found for type '${opType}' in the local knowledge base. Try searching with td_ops_query to find the correct type name.`,
            hint: "Operator types follow the pattern: noiseTOP, constantCHOP, mergeSOP, textDAT, etc."
          });
        }
        const match = matching.length > 0 ? matching[0] : null;
        const isPop = !match && popMatch !== null;
        if (isPop) {
          const __dirname6 = path2.dirname(fileURLToPath3(import.meta.url));
          const docPath2 = path2.join(
            __dirname6,
            "../data/pops/operators",
            `${popMatch.pageSlug}.json`
          );
          let doc2;
          try {
            const raw = await fs2.readFile(docPath2, "utf8");
            doc2 = JSON.parse(raw);
          } catch {
            return ok({
              found: true,
              type: opType,
              family: "POP",
              pageTitle: popMatch.pageTitle,
              url: popMatch.url,
              note: "Full parameter details not available in local database for this operator."
            });
          }
          return ok({
            found: true,
            type: opType,
            family: "POP",
            pageTitle: doc2.pageTitle,
            url: doc2.url,
            summary: typeof doc2.summary === "string" ? doc2.summary.substring(0, 1e3) : "",
            parameters: doc2.parameters ?? [],
            inputs: doc2.inputs ?? [],
            attributes: doc2.attributes ?? []
          });
        }
        const __dirname5 = path2.dirname(fileURLToPath3(import.meta.url));
        const docPath = path2.join(
          __dirname5,
          "../data/ops/operators",
          match.family,
          `${match.pageSlug}.json`
        );
        let doc;
        try {
          const raw = await fs2.readFile(docPath, "utf8");
          doc = JSON.parse(raw);
        } catch {
          return ok({
            found: true,
            type: opType,
            family: match.family,
            pageTitle: match.pageTitle,
            url: match.url,
            note: "Full parameter details not available in local database for this operator."
          });
        }
        return ok({
          found: true,
          type: opType,
          family: doc.family,
          pageTitle: doc.pageTitle,
          url: doc.url,
          summary: typeof doc.summary === "string" ? doc.summary.substring(0, 1e3) : "",
          parameters: doc.parameters ?? [],
          inputs: doc.inputs ?? [],
          attributes: doc.attributes ?? []
        });
      } catch (e) {
        return ok({
          found: false,
          type,
          error: e instanceof Error ? e.message : String(e),
          message: `Could not look up operator type '${type}' from the local knowledge base.`
        });
      }
    }
  );
