// mcp/src/tools/postValidate.ts
async function postModifyValidate(client, path7, parentPath, autoFix = true) {
  const checkPath = parentPath || path7;
  try {
    const health = await client.healthcheck(checkPath, false);
    const hasIssues = health && !health.ok && health.issueCount > 0;
    if (!hasIssues) {
      return {
        ok: true,
        issueCount: 0,
        issues: [],
        fixesApplied: 0,
        summary: "\u2705 Network healthy \u2014 no issues detected after modification."
      };
    }
    const issues = health.operators?.filter(
      (o) => o.hasIssues
    ) || [];
    let fixesApplied = 0;
    if (autoFix && issues.length > 0) {
      const fixResult = await autoFixExpressions(client, checkPath);
      fixesApplied = fixResult;
    }
    if (fixesApplied > 0) {
      const recheck = await client.healthcheck(checkPath, false);
      const stillHasIssues = recheck && !recheck.ok && recheck.issueCount > 0;
      if (!stillHasIssues) {
        return {
          ok: true,
          issueCount: 0,
          issues: [],
          fixesApplied,
          summary: `\u{1F527} Auto-fixed ${fixesApplied} expression error(s). Network now healthy.`
        };
      }
      const remaining = recheck.operators?.filter(
        (o) => o.hasIssues
      ) || [];
      return {
        ok: false,
        issueCount: remaining.length,
        issues: remaining.map((i) => ({
          path: i.path,
          name: i.name,
          opType: i.opType,
          errors: i.errors || "",
          warnings: i.warnings || ""
        })),
        fixesApplied,
        summary: `\u{1F527} Fixed ${fixesApplied} expression(s), but ${remaining.length} issue(s) remain. Run td_validate for full diagnosis.`
      };
    }
    return {
      ok: false,
      issueCount: issues.length,
      issues: issues.map((i) => ({
        path: i.path,
        name: i.name,
        opType: i.opType,
        errors: i.errors || "",
        warnings: i.warnings || ""
      })),
      fixesApplied: 0,
      summary: `\u26A0\uFE0F ${issues.length} issue(s) detected after modification. Run td_validate with auto_fix=true for full repair.`
    };
  } catch (e) {
    return {
      ok: false,
      issueCount: -1,
      issues: [],
      fixesApplied: 0,
      summary: `\u26A0\uFE0F Post-validation skipped: ${e.message || "unknown error"}`
    };
  }
}
async function autoFixExpressions(client, path7) {
  const safePath = path7.replace(/'/g, "\\'");
  const fixCode = `
import json, re

math_funcs = [
    'sin', 'cos', 'tan', 'asin', 'acos', 'atan', 'atan2',
    'sinh', 'cosh', 'tanh', 'asinh', 'acosh', 'atanh',
    'degrees', 'radians',
    'sqrt', 'cbrt', 'exp', 'exp2', 'expm1',
    'log', 'log2', 'log10', 'log1p',
    'floor', 'ceil', 'trunc',
    'fabs', 'fmod', 'gcd', 'hypot',
    'factorial', 'comb', 'perm',
]

SKIP_PATTERNS = ['/annotation/', '/opview/', '/marketplace']
pattern = re.compile(r'(?<!\\.)(?<!\\w)(' + '|'.join(math_funcs) + r')(?=\\s*\\()')

def should_skip(p):
    return any(pat in p for pat in SKIP_PATTERNS)

target = op('${safePath}')
if target is None:
    print(json.dumps({'fixed': 0}))
else:
    state = {'count': 0}
    def fix(node, depth=0):
        if node is None or depth > 30:
            return
        if should_skip(node.path):
            return
        try:
            for par in node.pars():
                if not par.expr:
                    continue
                original = par.expr
                new_expr = pattern.sub(lambda m: 'math.' + m.group(1), original)
                new_expr = new_expr.replace('math.math.', 'math.')
                if new_expr != original:
                    par.expr = new_expr
                    state['count'] += 1
        except:
            pass
        try:
            for child in node.children:
                fix(child, depth + 1)
        except:
            pass

    fix(target)
    print(json.dumps({'fixed': state['count']}))
`;
  try {
    const result = await client.execute(fixCode, "/");
    const parsed = JSON.parse(result.stdout || '{"fixed":0}');
    return parsed.fixed || 0;
  } catch {
    return 0;
  }
}
function getParentPath(path7) {
  const parts = path7.split("/").filter(Boolean);
  if (parts.length <= 1) return "/";
  return "/" + parts.slice(0, -1).join("/");
}

