init_zod();
init_popsValidate();
function registerParameterTools(server, client) {
  server.registerTool(
    "td_pars_get",
    {
      title: "Get Parameters",
      description: "Read current parameters from a TouchDesigner operator, including values, expressions, styles and menus.",
      inputSchema: {
        path: external_exports.string().describe("Operator path"),
        names: external_exports.array(external_exports.string()).optional().describe("Optional list of parameter names")
      }
    },
    async ({ path: opPath, names }) => {
      try {
        const result = await client.getParameters(opPath, names);
        return ok(result);
      } catch (e) {
        return err(e);
      }
    }
  );
  server.registerTool(
    "td_pars_set",
    {
      title: "Set Parameters",
      description: "Set TouchDesigner parameters transactionally. Supports plain values and expressions, with rollback on failure.",
      inputSchema: {
        path: external_exports.string().describe("Operator path"),
        transactional: external_exports.boolean().optional().describe("Rollback all changes if any update fails"),
        updates: external_exports.array(
          external_exports.object({
            name: external_exports.string(),
            value: external_exports.unknown().optional(),
            expr: external_exports.string().nullable().optional()
          })
        )
      }
    },
    async ({ path: opPath, updates, transactional }) => {
      try {
        const typeHint = await resolvePopTypeForPath(client, opPath);
        const validation = await validateParameterNamesForPath(
          client,
          opPath,
          updates.map((u) => u.name),
          typeHint ?? void 0
        );
        if (!validation.ok) {
          throw new Error(validation.detail);
        }
        const result = await client.setParameters(
          opPath,
          updates,
          transactional ?? true
        );
        const validation2 = await postModifyValidate(client, opPath);
        return ok({ ...result, validation });
      } catch (e) {
        return err(e);
      }
    }
  );
  server.registerTool(
    "td_set_operator_pars",
    {
      title: "Set Operator Parameters",
      description: "Set parameters on a TouchDesigner operator with a cleaner interface. Supports transactional rollback on failure.",
      inputSchema: {
        path: external_exports.string().describe("Operator path"),
        updates: external_exports.array(
          external_exports.object({
            name: external_exports.string().describe("Parameter name"),
            value: external_exports.unknown().optional().describe("Value to set")
          })
        ).describe("Array of parameter updates"),
        transactional: external_exports.boolean().optional().default(true).describe("Rollback all changes if any update fails (default: true)")
      }
    },
    async ({ path: opPath, updates, transactional }) => {
      try {
        const typeHint = await resolvePopTypeForPath(client, opPath);
        const validation = await validateParameterNamesForPath(
          client,
          opPath,
          updates.map((u) => u.name),
          typeHint ?? void 0
        );
        if (!validation.ok) return err(new Error(validation.detail));
        const apiUpdates = updates.map((u) => ({
          name: u.name,
          value: u.value
        }));
        const result = await client.setParameters(
          opPath,
          apiUpdates,
          transactional ?? true
        );
        const validation2 = await postModifyValidate(client, opPath);
        return ok({ ...result, validation });
      } catch (e) {
        return err(e);
      }
    }
  );
  server.registerTool(
    "td_pulse_param",
    {
      title: "Pulse Parameter",
      description: "Pulse a parameter on a TouchDesigner operator (e.g. Cook, Reset, Save).",
      inputSchema: {
        path: external_exports.string().describe("Operator path"),
        name: external_exports.string().describe("Parameter name to pulse")
      }
    },
    async ({ path: opPath, name }) => {
      try {
        const result = await client.pulseParam(opPath, name);
        return ok(result);
      } catch (e) {
        return err(e);
      }
    }
  );
  server.registerTool(
    "td_custom_parameters",
    {
      title: "Create Custom Parameters",
      description: "Create or update custom parameter pages on a TouchDesigner operator declaratively.",
      inputSchema: {
        path: external_exports.string().describe("Operator path"),
        page: external_exports.string().describe("Custom page name"),
        params: external_exports.array(
          external_exports.object({
            name: external_exports.string(),
            type: external_exports.string().optional().default("float"),
            default: external_exports.number().optional(),
            min: external_exports.number().optional(),
            max: external_exports.number().optional(),
            label: external_exports.string().optional()
          })
        ).describe("Parameter definitions")
      }
    },
    async ({ path: opPath, page, params }) => {
      try {
        const result = await client.customParameters(opPath, page, params);
        const validation = await postModifyValidate(client, opPath);
        return ok({ ...result, validation });
      } catch (e) {
        return err(e);
      }
    }
  );
}

