function registerWatchdogTools(server, client) {
  server.registerTool(
    "td_watch",
    {
      title: "Watch Performance",
      description: "Start or stop real-time performance monitoring in TouchDesigner. When started, polls getPerf() every `interval` seconds, accumulates samples in a circular buffer, and alerts when any operator exceeds `threshold` ms cook time. Call without arguments to get the current snapshot of the running watch.",
      inputSchema: {
        path: external_exports.string().optional().default("/").describe("Operator path to monitor (default: '/')"),
        interval: external_exports.number().optional().default(5).describe("Polling interval in seconds (minimum 1, default 5)"),
        threshold: external_exports.number().optional().default(50).describe("Cook time threshold in ms to trigger an alert (default: 50)"),
        max_samples: external_exports.number().int().min(1).max(3600).optional().default(60).describe("Max samples in circular history buffer (default: 60)"),
        action: external_exports.enum(["start", "stop", "snapshot"]).optional().default("snapshot").describe(
          "'start' begins monitoring, 'stop' ends it, 'snapshot' returns current state (default: snapshot)"
        )
      }
    },
    async ({ path: path7, interval, threshold, max_samples, action }) => {
      try {
        const resolvedPath = path7 ?? "/";
        const resolvedInterval = interval ?? 5;
        const resolvedThreshold = threshold ?? 50;
        const resolvedMaxSamples = max_samples ?? 60;
        switch (action) {
          case "start":
            startSession(client, resolvedPath, resolvedInterval, resolvedThreshold, resolvedMaxSamples);
            return ok({
              message: `Started performance watch on "${resolvedPath}" (interval=${resolvedInterval}s, threshold=${resolvedThreshold}ms, max_samples=${resolvedMaxSamples})`,
              ...buildSnapshot()
            });
          case "stop":
            stopSession();
            return ok({
              message: "Performance watch stopped.",
              running: false,
              alerts: [],
              history_length: 0,
              current_fps: 0,
              slowest: []
            });
          case "snapshot":
          default:
            return ok(buildSnapshot());
        }
      } catch (e) {
        return err(e);
      }
    }
  );
}

// mcp/src/tools/runner.ts
init_zod();
import { execSync } from "node:child_process";
import path4 from "node:path";
import fs5 from "node:fs";
import { fileURLToPath as fileURLToPath7 } from "node:url";
var RUNNER_TIMEOUT_MS = 6e4;
function testsDir() {
  const __dirname5 = path4.dirname(fileURLToPath7(import.meta.url));
  return path4.resolve(__dirname5, "../../tests");
}
function listAvailableTests() {
  const dir = testsDir();
  try {
    return fs5.readdirSync(dir).filter((f) => f.endsWith(".mjs")).map((f) => f.replace(/\.mjs$/, ""));
  } catch {
    return [];
  }
}
function registerRunnerTool(server, client) {
  server.registerTool(
    "td_run_test",
    {
      title: "Run Legacy Test",
      description: "Execute a legacy TouchDesigner MCP test script from the mcp/tests/ directory. Runs `node mcp/tests/<name>.mjs` with optional arguments and returns stdout, stderr, and the exit code. Timeout is 60 seconds. Use this to validate systems, run CI checks, or debug test failures.",
      inputSchema: {
        name: external_exports.string().describe(
          "Test file name (without .mjs extension), e.g. 'legacy_test_30systems'"
        ),
        args: external_exports.string().optional().describe("Optional command-line arguments passed to the test script")
      }
    },
    async ({ name, args }) => {
      try {
        const sanitised = name.replace(/\.\.\//g, "").replace(/\.mjs$/i, "");
        const testFile = path4.join(testsDir(), `${sanitised}.mjs`);
        if (!fs5.existsSync(testFile)) {
          const available = listAvailableTests();
          return ok({
            success: false,
            exitCode: -1,
            stdout: "",
            stderr: `Test '${sanitised}' not found.`,
            available
          });
        }
        const cmd = `node "${testFile}"${args ? " " + args : ""}`;
        let stdout = "";
        let stderr = "";
        let exitCode = -1;
        try {
          const output = execSync(cmd, {
            timeout: RUNNER_TIMEOUT_MS,
            encoding: "utf8",
            maxBuffer: 10 * 1024 * 1024,
            // 10 MB
            windowsHide: true
          });
          stdout = output;
          exitCode = 0;
        } catch (e) {
          stdout = e.stdout ?? "";
          stderr = e.stderr ?? "";
          exitCode = e.status ?? -1;
          if (e.killed || e.message && e.message.includes("timed out")) {
            stderr += "\n[TIMEOUT] Test exceeded 60 seconds and was killed.";
          }
        }
        return ok({
          success: exitCode === 0,
          exitCode,
          stdout,
          stderr,
          name: sanitised
        });
      } catch (e) {
        return err(e);
      }
    }
  );
}

// mcp/src/tools/validate.ts
init_zod();
function buildAutoFixCode(targetPath) {
  const safePath = targetPath.replace(/'/g, "\\'");
  return `
import json, re

def auto_fix_node(node_path):
    fixes = []
    target = op(node_path)
    if target is None:
        return {"fixed": [], "error": "Node not found: " + node_path}

    math_funcs = [
        'sin', 'cos', 'tan', 'asin', 'acos', 'atan', 'atan2',
        'sinh', 'cosh', 'tanh', 'asinh', 'acosh', 'atanh',
        'degrees', 'radians',
        'sqrt', 'cbrt', 'exp', 'exp2', 'expm1',
        'log', 'log2', 'log10', 'log1p',
        'floor', 'ceil', 'trunc',
        'fabs', 'fmod', 'gcd', 'hypot',
        'factorial', 'comb', 'perm',
    ]

    SKIP_PATTERNS = ['/annotation/', '/opview/', '/marketplace']
    combined_pattern = re.compile(
        r'(?<!\\.)(?<!\\w)(' + '|'.join(math_funcs) + r')(?=\\s*\\()'
    )

    def should_skip(path):
        return any(pat in path for pat in SKIP_PATTERNS)

    def fix_node(node, depth=0):
        if node is None or depth > 30:
            return
        try:
            if should_skip(node.path):
                return
            for par in node.pars():
                if not par.expr:
                    continue
                original = par.expr
                new_expr = combined_pattern.sub(
                    lambda m: 'math.' + m.group(1), original
                )
                new_expr = new_expr.replace('math.math.', 'math.')
                if new_expr != original:
                    par.expr = new_expr
                    fixes.append({
                        "path": node.path, "param": par.name,
                        "old": original[:120], "new": new_expr[:120],
                    })
        except:
            pass
        try:
            for child in node.children:
                fix_node(child, depth + 1)
        except:
            pass

    fix_node(target)
    return {"fixed": fixes, "count": len(fixes)}

result = auto_fix_node('${safePath}')
print(json.dumps(result))
`;
}
function buildClassifyCode(healthJson) {
  const escapedJson = healthJson.replace(/\\/g, "\\\\").replace(/'/g, "\\'").replace(/\$/g, "\\$");
  return `
import json, re

CATEGORY_PATTERNS = [
    ('expression_error', [
        r'AttributeError', r'NameError', r'SyntaxError', r'TypeError',
        r'not defined', r'has no attribute',
    ]),
    ('cook_loop', [r'Cook dependency loop', r'cook.*loop']),
    ('missing_file', [
        r'File not found', r'file not found', r'No such file', r'FileNotFoundError',
    ]),
    ('glsl_error', [
        r'Compile failed', r'compile.*error', r'GLSL.*error', r'shader.*error',
    ]),
]

SUGGESTED_ACTIONS = {
    'expression_error': [
        'Run td_validate with auto_fix=true to fix bare math functions',
        'Check that all Python imports (math, re, etc.) are available',
        'Verify parameter expression syntax in the TD operator',
    ],
    'cook_loop': [
        'Identify the circular dependency chain via operator expressions',
        'Try clearing the offending expression: op(path).par.X.expr = ""',
        'Consider bypassing the operator: op(path).bypass = True',
    ],
    'missing_file': [
        'Verify the file path exists on disk',
        'Set the DAT file parameter: op(path).par.file = "correct/path"',
        'Force-cook the DAT after fixing: op(path).cook(force=True)',
    ],
    'glsl_error': [
        'Check the GLSL source code in the glslTOP/glslPOP',
        'Verify uniform/attribute declarations match the TD environment',
        'Review GLSL compilation errors in the glsl1_info DAT',
    ],
    'needs_manual': [
        'Inspect the operator manually in the TD network editor',
        'Check TD documentation for this operator type',
        "Review the operator's error log via op(path).errors()",
    ],
}

def classify_issue(issue):
    path = issue.get('path', '')
    err = issue.get('error', '') or ''
    warn = issue.get('warning', '') or ''
    text = (err + ' ' + warn).lower()
    for category, patterns in CATEGORY_PATTERNS:
        for pat in patterns:
            if re.search(pat, text, re.IGNORECASE):
                return {
                    'path': path, 'category': category,
                    'error': err[:200] if err else None,
                    'warning': warn[:200] if warn else None,
                    'suggested_actions': SUGGESTED_ACTIONS.get(category, []),
                }
    return {
        'path': path, 'category': 'needs_manual',
        'error': err[:200] if err else None,
        'warning': warn[:200] if warn else None,
        'suggested_actions': SUGGESTED_ACTIONS['needs_manual'],
    }

health_json = '${escapedJson}'
health = json.loads(health_json)
issues = health.get('operators', [])
classified = [classify_issue(i) for i in issues]
summary = {}
for c in classified:
    cat = c['category']
    if cat not in summary:
        summary[cat] = []
    summary[cat].append(c)
counts = {cat: len(items) for cat, items in summary.items()}
result = {'total': len(classified), 'counts': counts, 'issues': classified, 'summary': summary}
print(json.dumps(result))
`;
}
function buildGlslCheckCode(targetPath) {
  const safePath = targetPath.replace(/'/g, "\\'");
  return `
import json
results = []
try:
    target = op('${safePath}')
    if target:
        def check_glsl(node, depth=0):
            if node is None or depth > 30:
                return
            try:
                if hasattr(node, 'OPType') and node.OPType == 'glslPOP':
                    info = op(node.path + '/glsl1_info')
                    if info and info.text:
                        txt = info.text.strip()
                        if 'Error' in txt or 'error' in txt:
                            results.append({"path": node.path, "status": "error", "info": txt[:300]})
                        elif 'Compiled Successfully' in txt:
                            results.append({"path": node.path, "status": "ok"})
                        else:
                            results.append({"path": node.path, "status": "unknown", "info": txt[:200]})
            except:
                pass
            try:
                for child in node.children:
                    check_glsl(child, depth + 1)
            except:
                pass
        check_glsl(target)
except Exception as e:
    results.append({"error": str(e)})
print(json.dumps(results))
`;
}
function buildPerfBudgetCode(targetPath, budgets) {
  const safePath = targetPath.replace(/'/g, "\\'");
  const maxCook = budgets.maxCookTimeMs ?? 16.67;
  const maxPts = budgets.maxPointCount ?? 1e6;
  const maxRes = budgets.maxResolution ?? 4096;
  const maxHz = budgets.maxRecookHz ?? 120;
  return `
import json

budgets = {
    'maxCookTimeMs': ${maxCook},
    'maxPointCount': ${maxPts},
    'maxResolution': ${maxRes},
    'maxRecookHz': ${maxHz},
}

violations = []
samples = []

target = op('${safePath}')
if target is None:
    print(json.dumps({"error": "Path not found: ${safePath}", "violations": [], "samples": []}))
else:
    def sample_node(node, depth=0):
        if node is None or depth > 30:
            return
        try:
            cook_time = 0
            try:
                if hasattr(node, 'cookTime'):
                    cook_time = node.cookTime
                elif hasattr(node, 'perf'):
                    cook_time = getattr(node, 'perf', 0)
            except:
                pass

            point_count = 0
            try:
                if hasattr(node, 'numPoints'):
                    np = node.numPoints
                    point_count = np() if callable(np) else np
            except:
                pass

            resolution = 0
            try:
                if hasattr(node, 'width') and hasattr(node, 'height'):
                    w = node.width
                    h = node.height
                    resolution = (w() if callable(w) else w) * (h() if callable(h) else h)
            except:
                pass

            sample = {
                'path': node.path,
                'opType': node.OPType if hasattr(node, 'OPType') else '?',
                'cookTimeMs': round(cook_time * 1000, 2) if cook_time else 0,
                'pointCount': point_count,
                'resolution': resolution,
            }
            samples.append(sample)

            # Check budgets
            if cook_time and cook_time * 1000 > budgets['maxCookTimeMs']:
                violations.append({
                    'path': node.path, 'metric': 'cookTimeMs',
                    'value': round(cook_time * 1000, 2),
                    'budget': budgets['maxCookTimeMs'],
                    'severity': 'warning' if cook_time * 1000 < budgets['maxCookTimeMs'] * 2 else 'critical',
                })
            if point_count > budgets['maxPointCount']:
                violations.append({
                    'path': node.path, 'metric': 'pointCount',
                    'value': point_count, 'budget': budgets['maxPointCount'],
                    'severity': 'warning' if point_count < budgets['maxPointCount'] * 2 else 'critical',
                })
            if resolution > budgets['maxResolution']:
                violations.append({
                    'path': node.path, 'metric': 'resolution',
                    'value': resolution, 'budget': budgets['maxResolution'],
                    'severity': 'warning',
                })
        except:
            pass
        try:
            for child in node.children:
                sample_node(child, depth + 1)
        except:
            pass

    sample_node(target)

    result = {
        'budgets': budgets,
        'violations': violations,
        'violationCount': len(violations),
        'sampleCount': len(samples),
        'samples': sorted(samples, key=lambda s: s.get('cookTimeMs', 0), reverse=True)[:20],
    }
    print(json.dumps(result))
`;
}
function buildStructuredReportCode(healthJson) {
  const escapedJson = healthJson.replace(/\\/g, "\\\\").replace(/'/g, "\\'").replace(/\$/g, "\\$");
  return `
import json, re

health = json.loads('${escapedJson}')
issues = health.get('operators', [])
reports = []

CAUSE_PATTERNS = {
    'expression_error': {
        'symptom': 'Operator shows red error flag with Python traceback',
        'cause': 'Bare math function used without math. prefix in parameter expression',
        'fix': 'Run td_validate auto_fix or manually prefix with math. (e.g. sin\u2192math.sin)',
        'verify': 'Re-run healthcheck \u2014 error flag should clear',
    },
    'cook_loop': {
        'symptom': 'TD shows "Cook dependency loop" warning, frame rate drops',
        'cause': 'Circular cook dependency between operators',
        'fix': 'Break the cycle: clear expression, bypass operator, or restructure network',
        'verify': 'Check cook time drops to near-zero for affected operators',
    },
    'missing_file': {
        'symptom': 'DAT shows "File not found" warning',
        'cause': 'File parameter points to non-existent path',
        'fix': 'Set correct file path or create the missing file',
        'verify': 'Force-cook the DAT: op(path).cook(force=True)',
    },
    'glsl_error': {
        'symptom': 'GLSL POP/TOP shows compilation error in glsl1_info',
        'cause': 'GLSL shader code has syntax error or undeclared identifier',
        'fix': 'Fix shader source \u2014 check uniforms, attributes, and GLSL version',
        'verify': 'Check glsl1_info DAT shows "Compiled Successfully"',
    },
    'needs_manual': {
        'symptom': 'Operator has unexpected behavior or warning',
        'cause': 'Requires manual inspection to determine root cause',
        'fix': 'Inspect in TD network editor, check operator documentation',
        'verify': 'Verify operator behavior matches expected output',
    },
}

CATEGORY_PATTERNS = [
    ('expression_error', [r'AttributeError', r'NameError', r'SyntaxError', r'TypeError', r'not defined']),
    ('cook_loop', [r'Cook dependency loop', r'cook.*loop']),
    ('missing_file', [r'File not found', r'No such file']),
    ('glsl_error', [r'Compile failed', r'GLSL.*error', r'shader.*error']),
]

for issue in issues:
    path = issue.get('path', '')
    name = issue.get('name', '')
    op_type = issue.get('opType', '')
    err = issue.get('error', '') or ''
    warn = issue.get('warning', '') or ''
    text = (err + ' ' + warn).lower()

    category = 'needs_manual'
    for cat, patterns in CATEGORY_PATTERNS:
        for pat in patterns:
            if re.search(pat, text, re.IGNORECASE):
                category = cat
                break
        if category != 'needs_manual':
            break

    template = CAUSE_PATTERNS[category]
    reports.append({
        'path': path,
        'name': name,
        'opType': op_type,
        'category': category,
        'symptom': template['symptom'],
        'error_detail': err[:200] if err else warn[:200],
        'cause': template['cause'],
        'fix': template['fix'],
        'verification': template['verify'],
    })

result = {
    'total': len(reports),
    'reports': reports,
    'by_category': {cat: len([r for r in reports if r['category'] == cat]) for cat in set(r['category'] for r in reports)} if reports else {},
}
print(json.dumps(result))
`;
}
function registerValidateTools(server, client) {
  server.registerTool(
    "td_validate",
    {
      title: "Validate & Auto-Fix",
      description: "Validate a TouchDesigner operator/network: force-cook, detect errors, classify issues by category (expression_error, cook_loop, missing_file, glsl_error, needs_manual), auto-fix common expression issues (bare sin\u2192math.sin, log\u2192math.log, etc.), check GLSL compilation, and re-validate. Returns errors found, fixes applied, issue classifications with suggested actions, and final status.",
      inputSchema: {
        path: external_exports.string().describe("Operator path to validate (e.g. '/project1/Pathtracer')"),
        recurse: external_exports.boolean().optional().default(true).describe("Validate descendants recursively (default: true)"),
        auto_fix: external_exports.boolean().optional().default(true).describe("Auto-fix common expression errors like bare sin/cos/log (default: true)")
      }
    },
    async ({ path: opPath, recurse, auto_fix }) => {
      try {
        const result = {
          path: opPath,
          recurse: recurse ?? true,
          auto_fix: auto_fix ?? true,
          steps: []
        };
        const health = await client.healthcheck(opPath, recurse ?? true);
        result.steps.push({ step: "healthcheck", result: health });
        const hasErrors = health && !health.ok && health.issueCount > 0;
        if ((auto_fix ?? true) && hasErrors) {
          const fixCode = buildAutoFixCode(opPath);
          const fixResult = await client.execute(fixCode, "/");
          result.steps.push({ step: "auto_fix", result: fixResult });
          try {
            result.errors_fixed = JSON.parse(
              fixResult.stdout || "{}"
            );
          } catch {
            result.errors_fixed = { raw: fixResult.stdout };
          }
          const recheck = await client.healthcheck(opPath, recurse ?? true);
          result.steps.push({ step: "recheck", result: recheck });
          result.final_status = recheck.ok ? "healthy" : "has_issues";
        } else {
          result.final_status = hasErrors ? "has_issues" : "healthy";
        }
        const glslCheck = await client.execute(
          buildGlslCheckCode(opPath),
          "/"
        );
        let glslResults = [];
        try {
          glslResults = JSON.parse(glslCheck.stdout || "[]");
        } catch {
          glslResults = [];
        }
        result.steps.push({ step: "glsl_check", result: glslResults });
        const glslErrors = glslResults.filter((r) => r.status === "error");
        if (glslErrors.length > 0) {
          result.final_status = "has_issues";
          result.glsl_errors = glslErrors;
        }
        let classifyResults = {};
        try {
          const healthJson = JSON.stringify(health);
          const classifyCode = buildClassifyCode(healthJson);
          const classifyResult = await client.execute(classifyCode, "/");
          try {
            classifyResults = JSON.parse(
              classifyResult.stdout || "{}"
            );
          } catch {
            classifyResults = {};
          }
          result.steps.push({ step: "classify_issues", result: classifyResults });
          result.classification = classifyResults;
        } catch {
          result.steps.push({
            step: "classify_issues",
            result: { error: "Classification failed" }
          });
          result.classification = {};
        }
        let structuredReports = {};
        if (hasErrors) {
          try {
            const healthJson = JSON.stringify(health);
            const reportCode = buildStructuredReportCode(healthJson);
            const reportResult = await client.execute(reportCode, "/");
            try {
              structuredReports = JSON.parse(
                reportResult.stdout || "{}"
              );
            } catch {
              structuredReports = {};
            }
            result.steps.push({
              step: "structured_reports",
              result: structuredReports
            });
            result.structuredReports = structuredReports;
          } catch {
            result.steps.push({
              step: "structured_reports",
              result: { error: "Report generation failed" }
            });
          }
        }
        result.summary = {
          total_issues_before: health?.issueCount ?? 0,
          fixes_applied: result.errors_fixed?.count ?? 0,
          glsl_shaders_checked: glslResults.length,
          glsl_errors: glslErrors.length,
          classified: classifyResults.counts ?? {},
          structured_report_count: structuredReports.total ?? 0,
          final_status: result.final_status
        };
        return ok(result);
      } catch (e) {
        return err(e);
      }
    }
  );
  server.registerTool(
    "td_perf_budget",
    {
      title: "Performance Budget Check",
      description: "Check performance of operators against configurable budgets. Monitors cook time, point count, resolution, and recook frequency. Returns violations sorted by severity with actionable fix suggestions. Tier 4 validation from the mcp_td_v2 testing protocols.",
      inputSchema: {
        path: external_exports.string().describe("Root path to profile (e.g. '/project1/mySystem')"),
        max_cook_time_ms: external_exports.number().optional().default(16.67).describe("Max cook time per operator in ms (default: 16.67 = 60fps budget)"),
        max_point_count: external_exports.number().optional().default(1e6).describe("Max point count per POP operator (default: 1,000,000)"),
        max_resolution: external_exports.number().optional().default(4096).describe("Max total pixel count (width*height) for TOP operators (default: 4096)"),
        max_recook_hz: external_exports.number().optional().default(120).describe("Max expected recook frequency in Hz (default: 120)")
      }
    },
    async ({
      path: opPath,
      max_cook_time_ms,
      max_point_count,
      max_resolution,
      max_recook_hz
    }) => {
      try {
        const code = buildPerfBudgetCode(opPath, {
          maxCookTimeMs: max_cook_time_ms,
          maxPointCount: max_point_count,
          maxResolution: max_resolution,
          maxRecookHz: max_recook_hz
        });
        const execResult = await client.execute(code, "/");
        let perfResult;
        try {
          perfResult = JSON.parse(execResult.stdout || "{}");
        } catch {
          perfResult = { error: "Failed to parse performance data" };
        }
        const suggestions = [];
        if (perfResult.violations) {
          for (const v of perfResult.violations) {
            if (v.metric === "cookTimeMs") {
              suggestions.push(
                `\u26A0\uFE0F ${v.path}: cook time ${v.value}ms exceeds budget ${v.budget}ms \u2014 reduce complexity, lower iteration count, or cache intermediate results`
              );
            } else if (v.metric === "pointCount") {
              suggestions.push(
                `\u26A0\uFE0F ${v.path}: ${v.value.toLocaleString()} points exceeds budget ${v.budget.toLocaleString()} \u2014 reduce particle count, apply thin POP, or use LOD`
              );
            } else if (v.metric === "resolution") {
              suggestions.push(
                `\u26A0\uFE0F ${v.path}: resolution ${v.value}px exceeds budget ${v.budget}px \u2014 reduce TOP resolution or use downscaling`
              );
            }
          }
        }
        return ok({
          ...perfResult,
          suggestions,
          overallStatus: (perfResult.violationCount ?? 0) === 0 ? "within_budget" : "budget_exceeded"
        });
      } catch (e) {
        return err(e);
      }
    }
  );
}

