init_zod();
function validatePythonSyntax(code) {
  const errors = [];
  const warnings = [];
  const mathFuncs = [
    "sin",
    "cos",
    "tan",
    "asin",
    "acos",
    "atan",
    "atan2",
    "sqrt",
    "cbrt",
    "exp",
    "exp2",
    "expm1",
    "log",
    "log2",
    "log10",
    "log1p",
    "floor",
    "ceil",
    "trunc",
    "degrees",
    "radians",
    "fabs",
    "fmod",
    "hypot"
  ];
  const bareMathPattern = new RegExp(
    `(?<!\\.)(?<!\\w)(${mathFuncs.join("|")})(?=\\s*\\()`,
    "g"
  );
  const bareMatches = code.match(bareMathPattern);
  if (bareMatches && bareMatches.length > 0) {
    const unique = [...new Set(bareMatches)];
    warnings.push(
      `Bare math functions detected: ${unique.join(", ")} \u2014 these need 'math.' prefix in TD (e.g. math.sin). Auto-fix available via td_validate.`
    );
  }
  const nameErrors = [
    { pattern: /(?<!\w)print\s*[^(]/g, msg: "print without parentheses (Python 3 requires print())" },
    { pattern: /except\s*:/g, msg: "bare except clause (consider using 'except Exception')" },
    { pattern: /(?<!\w)input\s*=/g, msg: "'input' used as variable name \u2014 shadows built-in" }
  ];
  for (const { pattern, msg } of nameErrors) {
    if (pattern.test(code)) {
      warnings.push(msg);
    }
  }
  const singleQuotes = (code.match(/(?<!\\)'/g) || []).length;
  const doubleQuotes = (code.match(/(?<!\\)"/g) || []).length;
  if (singleQuotes % 2 !== 0) {
    errors.push("Odd number of single quotes \u2014 possible unclosed string literal");
  }
  if (doubleQuotes % 2 !== 0) {
    errors.push("Odd number of double quotes \u2014 possible unclosed string literal");
  }
  if (code.includes("f'") || code.includes('f"')) {
    warnings.push("f-string detected \u2014 ensure no user-controlled input is interpolated without escaping");
  }
  return { passed: errors.length === 0, errors, warnings };
}
function validatePathSafety(paths) {
  const errors = [];
  const warnings = [];
  for (const p of paths) {
    if (!p.startsWith("/")) {
      errors.push(`Path '${p}' must start with '/'`);
    }
    if (p.includes("'")) {
      errors.push(`Path '${p}' contains single quotes \u2014 injection risk in Python exec`);
    }
    if (p.includes("\\")) {
      errors.push(`Path '${p}' contains backslashes \u2014 use forward slashes for TD paths`);
    }
    const internalPatterns = ["/annotation/", "/opview/", "/marketplace"];
    for (const pat of internalPatterns) {
      if (p.includes(pat)) {
        warnings.push(`Path '${p}' references TD internal path '${pat}' \u2014 may be auto-generated`);
      }
    }
    if (p.includes("//")) {
      warnings.push(`Path '${p}' contains double slashes \u2014 may cause 'operator not found'`);
    }
  }
  return { passed: errors.length === 0, errors, warnings };
}
async function checkDependencies(client) {
  const errors = [];
  const warnings = [];
  try {
    const info = await client.getInfo();
    const infoAny = info;
    const version2 = infoAny?.version || infoAny?.buildVersion || "";
    if (version2) {
      const match = version2.match(/(\d{4})\.(\d+)/);
      if (match) {
        const year = parseInt(match[1], 10);
        if (year < 2025) {
          warnings.push(
            `TouchDesigner version ${version2} may be below recommended 2025+ \u2014 some POP features may not be available`
          );
        }
      }
    }
    if (infoAny && !infoAny.error) {
    } else {
      errors.push("Cannot reach TouchDesigner \u2014 verify TDAPI_HOST and TDAPI_PORT are correct");
    }
  } catch (e) {
    errors.push(`TD connection check failed: ${e.message || String(e)}`);
  }
  return { passed: errors.length === 0, errors, warnings };
}
function validateJsonIntegrity(jsonStrings) {
  const errors = [];
  const warnings = [];
  for (let i = 0; i < jsonStrings.length; i++) {
    const raw = jsonStrings[i];
    if (raw.includes("```json") || raw.includes("```")) {
      errors.push(
        `JSON string ${i + 1} contains markdown code fences \u2014 LLM output should be raw JSON`
      );
    }
    try {
      const parsed = JSON.parse(raw);
      if (parsed === null || parsed === void 0) {
        warnings.push(`JSON string ${i + 1} parses to null/undefined`);
      }
      if (typeof parsed === "object" && Object.keys(parsed).length === 0) {
        warnings.push(`JSON string ${i + 1} parses to empty object {}`);
      }
    } catch (e) {
      errors.push(`JSON string ${i + 1} is not valid JSON: ${e.message}`);
    }
  }
  return { passed: errors.length === 0, errors, warnings };
}
var INVALID_CROSS_FAMILY = {
  POP: ["SOP", "TOP", "CHOP", "DAT"],
  SOP: ["POP"],
  TOP: ["POP"],
  CHOP: ["POP"],
  DAT: ["POP"]
};
var VALID_BRIDGES = {
  "POP\u2192SOP": "renderPOP or geometryCOMP",
  "SOP\u2192POP": "attributePOP or geometryCOMP",
  "POP\u2192TOP": "renderPOP \u2192 nullTOP",
  "TOP\u2192POP": "choptoTOP \u2192 attributePOP",
  "POP\u2192CHOP": "chopToPOP or selectCHOP",
  "CHOP\u2192POP": "selectCHOP \u2192 attributePOP",
  "POP\u2192DAT": "not directly supported \u2014 use renderTOP \u2192 DAT",
  "DAT\u2192POP": "not directly supported \u2014 use tableDAT \u2192 parameter expression"
};
function validateCrossFamilyConnections(code) {
  const errors = [];
  const warnings = [];
  const createPattern = /\.(create|Create)\((?:td\.)?(\w+)(TOP|CHOP|SOP|DAT|POP|COMP)/g;
  const createdTypes = [];
  let match;
  while ((match = createPattern.exec(code)) !== null) {
    const family = match[3];
    createdTypes.push(family);
  }
  const families = [...new Set(createdTypes)];
  const crossFamilyPairs = [];
  for (const src of families) {
    for (const tgt of families) {
      if (src !== tgt && INVALID_CROSS_FAMILY[src]?.includes(tgt)) {
        crossFamilyPairs.push([src, tgt]);
      }
    }
  }
  for (const [src, tgt] of crossFamilyPairs) {
    const bridgeKey = `${src}\u2192${tgt}`;
    const bridge = VALID_BRIDGES[bridgeKey] || "adapter operator";
    warnings.push(
      `Cross-family connection detected: ${src} \u2192 ${tgt}. Invalid without adapter. Bridge with: ${bridge}`
    );
  }
  const popCreatePattern = /\.(create|Create)\((?:td\.)?(\w+POP)/g;
  let popMatch;
  while ((popMatch = popCreatePattern.exec(code)) !== null) {
    const popType = popMatch[2];
    if (popType === "particlePOP" && !code.includes("particlesupdatepop")) {
      warnings.push(
        "particlePOP created but particlesupdatepop parameter not set \u2014 feedback loop will not work. Set it to the downstream nullPOP name."
      );
    }
    if (popType === "noisePOP" && !code.includes("inputConnectors[0].connect")) {
      warnings.push(
        "noisePOP may need an input connection \u2014 it cannot run standalone."
      );
    }
  }
  return { passed: errors.length === 0, errors, warnings };
}
function registerSyntacticCheckTools(server, client) {
  server.registerTool(
    "td_syntactic_check",
    {
      title: "Pre-Execution Syntactic Check",
      description: "Validate Python code, TD paths, JSON, and environment dependencies BEFORE sending to TD. Catches: bare math functions (sin\u2192math.sin), unclosed strings, path injection risks, markdown-wrapped JSON, TD version compatibility, connection status, and cross-family connection errors (POP\u2192SOP, POP\u2192TOP without adapter). Run this before td_execute or td_network_plan to prevent runtime errors.",
      inputSchema: {
        code: external_exports.string().optional().describe("Python code to validate before execution"),
        paths: external_exports.array(external_exports.string()).optional().describe("TD operator paths to validate for safety"),
        json_strings: external_exports.array(external_exports.string()).optional().describe("JSON strings to validate for structural integrity"),
        check_dependencies: external_exports.boolean().optional().default(false).describe("Also verify TD connection and version (requires live TD)")
      }
    },
    async ({ code, paths, json_strings, check_dependencies }) => {
      try {
        const result = {
          ok: true,
          checks: {
            pythonSyntax: { passed: true, errors: [], warnings: [] },
            pathSafety: { passed: true, errors: [], warnings: [] },
            dependencyCheck: { passed: true, errors: [], warnings: [] },
            jsonIntegrity: { passed: true, errors: [], warnings: [] }
          },
          summary: "",
          suggestions: []
        };
        if (code) {
          result.checks.pythonSyntax = validatePythonSyntax(code);
          if (!result.checks.pythonSyntax.passed) result.ok = false;
          for (const w of result.checks.pythonSyntax.warnings) {
            result.suggestions.push(w);
          }
          const crossFamilyResult = validateCrossFamilyConnections(code);
          if (!crossFamilyResult.passed) {
            result.checks.pathSafety.passed = false;
            result.checks.pathSafety.errors.push(...crossFamilyResult.errors);
            result.ok = false;
          }
          result.checks.pathSafety.warnings.push(...crossFamilyResult.warnings);
          for (const w of crossFamilyResult.warnings) {
            result.suggestions.push(w);
          }
        }
        if (paths && paths.length > 0) {
          result.checks.pathSafety = validatePathSafety(paths);
          if (!result.checks.pathSafety.passed) result.ok = false;
        }
        if (json_strings && json_strings.length > 0) {
          result.checks.jsonIntegrity = validateJsonIntegrity(json_strings);
          if (!result.checks.jsonIntegrity.passed) result.ok = false;
        }
        if (check_dependencies) {
          result.checks.dependencyCheck = await checkDependencies(client);
          if (!result.checks.dependencyCheck.passed) result.ok = false;
        }
        const allChecks = Object.values(result.checks);
        const totalErrors = allChecks.reduce((sum, c) => sum + c.errors.length, 0);
        const totalWarnings = allChecks.reduce((sum, c) => sum + c.warnings.length, 0);
        if (totalErrors === 0 && totalWarnings === 0) {
          result.summary = "\u2705 All syntactic checks passed \u2014 safe to execute.";
        } else if (totalErrors === 0) {
          result.summary = `\u26A0\uFE0F ${totalWarnings} warning(s) but no errors \u2014 safe to execute with caution.`;
        } else {
          result.summary = `\u274C ${totalErrors} error(s) found \u2014 fix before executing to prevent runtime failures.`;
        }
        return ok(result);
      } catch (e) {
        return err(e);
      }
    }
  );
}

// mcp/src/tools/tdn.ts
init_zod();
import * as fs6 from "node:fs";
import * as path5 from "node:path";
import { execSync as execSync2 } from "node:child_process";
function buildExportCode(rootPath, outputFilePath, includeDatContent, includeStorage) {
  const safePath = rootPath.replace(/'/g, "\\'");
  const safeFile = outputFilePath.replace(/\\/g, "/").replace(/'/g, "\\'");
  return `
import json, os, sys, time, datetime

# \u2500\u2500 Configuration \u2500\u2500
INCLUDE_DAT_CONTENT = ${includeDatContent ? "True" : "False"}
INCLUDE_STORAGE = ${includeStorage ? "True" : "False"}
SKIP_PARAMS = {
    'preview', 'file', 'syncfile', 'externaltox', 'reloaddat',
    'clone', 'opshortcut', 'opId', 'viewer', 'render',
    'bypass', 'lock', 'display',
}
SKIP_STORAGE_KEYS = {'_gm', '_tdn_palette_handling'}

# \u2500\u2500 Defaults for comparison \u2500\u2500
DEFAULT_NODE_SIZE = [200, 100]
DEFAULT_COLOR = [0.545, 0.545, 0.545]

def serialize_value(val):
    if val is None:
        return None
    if isinstance(val, bool):
        return val
    if isinstance(val, (int, float)):
        return val
    if isinstance(val, str):
        return val
    if isinstance(val, (list, tuple)):
        return [serialize_value(v) for v in val]
    if isinstance(val, dict):
        return {k: serialize_value(v) for k, v in val.items()}
    return str(val)

def get_par_value(par):
    try:
        if par.isExpression:
            return '=' + par.expr
        if par.isBind:
            return '~' + par.bindExpr
        return serialize_value(par.val)
    except:
        return None

def get_non_default_pars(node):
    pars = {}
    try:
        for par in node.pars:
            try:
                if par.name.lower() in SKIP_PARAMS:
                    continue
                if par.readOnly:
                    continue
                val = get_par_value(par)
                if val is None:
                    continue
                default = par.default
                if val == default:
                    continue
                pars[par.name] = val
            except:
                pass
    except:
        pass
    return pars

def get_flags(node):
    flags = []
    flag_names = ['bypass', 'lock', 'display', 'render', 'viewer', 'expose', 'allowCooking']
    try:
        for f in flag_names:
            try:
                val = getattr(node, f, None)
                if val is not None:
                    if not val:
                        flags.append('-' + f)
            except:
                pass
    except:
        pass
    return flags if flags else None

def get_connections(node):
    inputs = []
    try:
        for ic in node.inputConnectors:
            try:
                if len(ic.connections) > 0:
                    src = ic.connections[0].owner
                    if src and src.parent() == node.parent():
                        inputs.append(src.name)
                    elif src:
                        inputs.append(src.path)
                    else:
                        inputs.append(None)
                else:
                    inputs.append(None)
            except:
                inputs.append(None)
    except:
        pass
    while inputs and inputs[-1] is None:
        inputs.pop()
    return inputs if inputs else None

def get_storage(node):
    storage = {}
    try:
        for key in node.storage:
            if key in SKIP_STORAGE_KEYS:
                continue
            try:
                val = node.storage[key]
                storage[key] = serialize_value(val)
            except:
                pass
    except:
        pass
    return storage if storage else None

def get_custom_pars(node):
    pages = {}
    try:
        for page in node.customPages:
            page_pars = []
            for par in page.pars:
                pdef = {'name': par.name, 'style': par.style}
                if par.label and par.label != par.name:
                    pdef['label'] = par.label
                val = get_par_value(par)
                if val is not None:
                    default = par.default
                    if val != default:
                        if isinstance(val, list):
                            pdef['values'] = val
                        else:
                            pdef['value'] = val
                page_pars.append(pdef)
            if page_pars:
                pages[page.name] = page_pars
    except:
        pass
    return pages if pages else None

def get_dat_content(node):
    if not INCLUDE_DAT_CONTENT:
        return None
    try:
        if hasattr(node, 'text'):
            txt = node.text
            if txt and len(txt.strip()) > 0:
                try:
                    rows = []
                    for i in range(node.numRows):
                        row = []
                        for j in range(node.numCols):
                            row.append(node[i][j] if node[i][j] is not None else '')
                        rows.append(row)
                    if len(rows) > 0 and len(rows[0]) > 1:
                        return {'data': rows, 'format': 'table'}
                except:
                    pass
                return {'data': txt, 'format': 'text'}
    except:
        pass
    return None

def get_annotations(node):
    annotations = []
    try:
        for child in node.children:
            if hasattr(child, 'OPType') and child.OPType in ('annotatCOMP', 'commentCOMP', 'networkboxCOMP'):
                ann = {
                    'name': child.name,
                    'mode': child.OPType.replace('COMP', ''),
                }
                try:
                    title = getattr(child, 'title', None)
                    if title:
                        ann['title'] = title
                except:
                    pass
                try:
                    txt = getattr(child, 'text', None)
                    if txt:
                        ann['text'] = txt
                except:
                    pass
                try:
                    pos = [child.par.x if hasattr(child.par, 'x') else 0, child.par.y if hasattr(child.par, 'y') else 0]
                    if pos[0] != 0 or pos[1] != 0:
                        ann['position'] = pos
                except:
                    pass
                try:
                    sz = [child.par.w if hasattr(child.par, 'w') else 200, child.par.h if hasattr(child.par, 'h') else 100]
                    ann['size'] = sz
                except:
                    ann['size'] = [200, 100]
                annotations.append(ann)
    except:
        pass
    return annotations if annotations else None

def export_operator(node, depth=0):
    if node is None or depth > 50:
        return None
    try:
        op_type = node.OPType if hasattr(node, 'OPType') else '?'
    except:
        op_type = '?'

    op_data = {'name': node.name, 'type': op_type}

    try:
        if hasattr(node, 'par') and hasattr(node.par, 'x') and hasattr(node.par, 'y'):
            x = node.par.x
            y = node.par.y
            if x != 0 or y != 0:
                op_data['position'] = [x, y]
    except:
        pass

    try:
        if hasattr(node, 'par') and hasattr(node.par, 'w') and hasattr(node.par, 'h'):
            w = node.par.w
            h = node.par.h
            if w != DEFAULT_NODE_SIZE[0] or h != DEFAULT_NODE_SIZE[1]:
                op_data['size'] = [w, h]
    except:
        pass

    try:
        clr = getattr(node, 'color', None)
        if clr and list(clr) != DEFAULT_COLOR:
            op_data['color'] = list(clr)
    except:
        pass

    try:
        cmt = getattr(node, 'comment', None)
        if cmt and cmt.strip():
            op_data['comment'] = cmt
    except:
        pass

    try:
        tags = list(node.tags) if hasattr(node, 'tags') else []
        if tags:
            op_data['tags'] = tags
    except:
        pass

    pars = get_non_default_pars(node)
    if pars:
        op_data['parameters'] = pars

    cpars = get_custom_pars(node)
    if cpars:
        op_data['custom_pars'] = cpars

    flags = get_flags(node)
    if flags:
        op_data['flags'] = flags

    storage = get_storage(node)
    if storage:
        op_data['storage'] = storage

    inputs = get_connections(node)
    if inputs:
        op_data['inputs'] = inputs

    dat = get_dat_content(node)
    if dat:
        op_data['dat_content'] = dat['data']
        op_data['dat_content_format'] = dat['format']

    # Children (for COMPs) \u2014 use child_ops list, NOT child_data
    try:
        if hasattr(node, 'children') and len(node.children) > 0:
            child_ops = []
            for child in node.children:
                try:
                    if hasattr(child, 'OPType') and child.OPType not in ('annotatCOMP', 'commentCOMP', 'networkboxCOMP'):
                        child_result = export_operator(child, depth + 1)
                        if child_result:
                            child_ops.append(child_result)
                except:
                    pass
            if child_ops:
                op_data['children'] = child_ops
    except:
        pass

    anns = get_annotations(node)
    if anns:
        op_data['annotations'] = anns

    return op_data

# \u2500\u2500 Main Export \u2500\u2500
target = op('${safePath}')
if target is None:
    print(json.dumps({'success': False, 'error': 'Path not found: ${safePath}'}))
else:
    operators = []
    try:
        for child in target.children:
            try:
                if hasattr(child, 'OPType') and child.OPType not in ('annotatCOMP', 'commentCOMP', 'networkboxCOMP'):
                    op_data = export_operator(child)
                    if op_data:
                        operators.append(op_data)
            except:
                pass
    except:
        pass

    tdn = {
        'format': 'tdn',
        'version': '1.4',
        'build': None,
        'generator': 'TouchDesigner-MCP/3.0',
        'td_build': app.version if hasattr(app, 'version') else 'unknown',
        'exported_at': datetime.datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ'),
        'network_path': '${safePath}',
        'type': target.OPType if hasattr(target, 'OPType') else 'baseCOMP',
        'options': {
            'include_dat_content': INCLUDE_DAT_CONTENT,
            'include_storage': INCLUDE_STORAGE,
        },
        'operators': operators,
    }

    try:
        out_path = '${safeFile}'
        os.makedirs(os.path.dirname(out_path) if os.path.dirname(out_path) else '.', exist_ok=True)
        with open(out_path, 'w', encoding='utf-8') as f:
            json.dump(tdn, f, indent='\\t', ensure_ascii=False)
        result = {
            'success': True,
            'path': '${safePath}',
            'output_file': out_path,
            'operator_count': len(operators),
            'file_size': os.path.getsize(out_path),
        }
    except Exception as e:
        result = {'success': False, 'error': str(e)}

    print(json.dumps(result))
`;
}
function buildImportCode(tdnFilePath, targetPath) {
  const safeFile = tdnFilePath.replace(/\\/g, "/").replace(/'/g, "\\'");
  const safeTarget = targetPath.replace(/'/g, "\\'");
  return `
import json, os, sys

def resolve_type(typ):
    mapping = {
        'baseCOMP': baseCOMP, 'containerCOMP': containerCOMP,
        'geometryCOMP': geometryCOMP, 'cameraCOMP': cameraCOMP,
        'lightCOMP': lightCOMP, 'nullCOMP': nullCOMP,
        'animationCOMP': animationCOMP, 'windowCOMP': windowCOMP,
        'textDAT': textDAT, 'tableDAT': tableDAT, 'executeDAT': executeDAT,
        'selectDAT': selectDAT, 'scriptDAT': scriptDAT, 'webClientDAT': webClientDAT,
        'noiseTOP': noiseTOP, 'blurTOP': blurTOP, 'nullTOP': nullTOP,
        'compositeTOP': compositeTOP, 'levelTOP': levelTOP, 'transformTOP': transformTOP,
        'constantTOP': constantTOP, 'renderTOP': renderTOP, 'glslTOP': glslTOP,
        'selectTOP': selectTOP, 'moviefileinTOP': moviefileinTOP,
        'noiseCHOP': noiseCHOP, 'constantCHOP': constantCHOP, 'mathCHOP': mathCHOP,
        'nullCHOP': nullCHOP, 'selectCHOP': selectCHOP, 'lagCHOP': lagCHOP,
        'waveCHOP': waveCHOP, 'speedCHOP': speedCHOP, 'trailCHOP': trailCHOP,
        'patternCHOP': patternCHOP, 'timerCHOP': timerCHOP,
        'noiseSOP': noiseSOP, 'sphereSOP': sphereSOP, 'boxSOP': boxSOP,
        'gridSOP': gridSOP, 'nullSOP': nullSOP, 'mergeSOP': mergeSOP,
        'particlePOP': particlePOP, 'forcePOP': forcePOP, 'noisePOP': noisePOP,
        'nullPOP': nullPOP, 'glslPOP': glslPOP, 'popToCHOP': popToCHOP,
        'pythonCOMP': pythonCOMP, 'localTimeCOMP': localTimeCOMP,
        'parCOMP': parCOMP, 'webRendererCOMP': webRendererCOMP,
        'choptoCHOP': choptoCHOP, 'holdCHOP': holdCHOP,
        'audioCHOP': audioCHOP, 'audioDeviceInCHOP': audioDeviceInCHOP,
        'fbxAnimInCHOP': fbxAnimInCHOP, 'fileInCHOP': fileInCHOP,
        'opCHOP': opCHOP, 'countCHOP': countCHOP, 'evalCHOP': evalCHOP,
        'lookupCHOP': lookupCHOP, 'midiInCHOP': midiInCHOP,
        'noiseTOP': noiseTOP, 'videoDeviceInTOP': videoDeviceInTOP,
        'textTOP': textTOP, 'circleTOP': circleTOP, 'rectangleTOP': rectangleTOP,
        'gradientTOP': gradientTOP, 'slopeTOP': slopeTOP,
        'depthTOP': depthTOP, 'displaceTOP': displaceTOP,
        'edgeTOP': edgeTOP, 'sharpenTOP': sharpenTOP,
        'phongMAT': phongMAT, 'pbrMAT': pbrMAT, 'glslMAT': glslMAT,
        'constantMAT': constantMAT, 'selectMAT': selectMAT,
        'lineMAT': lineMAT, 'wireframeMAT': wireframeMAT,
        'moviefileoutTOP': moviefileoutTOP, 'selectSOP': selectSOP,
        'copySOP': copySOP, 'transformSOP': transformSOP,
        'facetSOP': facetSOP, 'subdivideSOP': subdivideSOP,
        'switchDAT': switchDAT, 'convertDAT': convertDAT,
        'dattoCHOP': dattoCHOP, 'selectCHOP': selectCHOP,
        'patternCHOP': patternCHOP, 'lagCHOP': lagCHOP,
        'speedCHOP': speedCHOP, 'trailCHOP': trailCHOP,
        'countCHOP': countCHOP, 'timerCHOP': timerCHOP,
        'evalCHOP': evalCHOP, 'lookupCHOP': lookupCHOP,
    }
    return mapping.get(typ, baseCOMP)

def set_par_value(node, name, val):
    try:
        par = getattr(node.par, name, None)
        if par is None:
            return
        if isinstance(val, str) and len(val) > 0 and val[0] == '=':
            par.expr = val[1:]
        elif isinstance(val, str) and len(val) > 0 and val[0] == '~':
            par.bindExpr = val[1:]
        elif isinstance(val, list):
            par.val = val
        else:
            par.val = val
    except:
        pass

def set_flags(node, flags):
    if not flags:
        return
    for f in flags:
        try:
            if f.startswith('-'):
                setattr(node, f[1:], False)
            else:
                setattr(node, f, True)
        except:
            pass

def set_connections(node, inputs):
    if not inputs:
        return
    parent = node.parent()
    if parent is None:
        return
    for idx, src_name in enumerate(inputs):
        if src_name is None:
            continue
        try:
            src = op(src_name) if src_name.startswith('/') else parent.op(src_name)
            if src is not None and idx < len(node.inputConnectors):
                node.inputConnectors[idx].connect(src)
        except:
            pass

def import_operator(parent, op_data, depth=0):
    if op_data is None or depth > 50:
        return None
    name = op_data.get('name', 'op')
    typ = op_data.get('type', 'nullTOP')
    try:
        op_cls = resolve_type(typ)
        node = parent.create(op_cls, name)
    except Exception as e:
        return None

    pos = op_data.get('position')
    if pos and hasattr(node.par, 'x') and hasattr(node.par, 'y'):
        try:
            node.par.x = pos[0]
            node.par.y = pos[1]
        except:
            pass

    sz = op_data.get('size')
    if sz and hasattr(node.par, 'w') and hasattr(node.par, 'h'):
        try:
            node.par.w = sz[0]
            node.par.h = sz[1]
        except:
            pass

    clr = op_data.get('color')
    if clr:
        try:
            node.color = clr
        except:
            pass

    cmt = op_data.get('comment')
    if cmt:
        try:
            node.comment = cmt
        except:
            pass

    tags = op_data.get('tags')
    if tags:
        try:
            for t in tags:
                node.tags.add(t)
        except:
            pass

    pars = op_data.get('parameters', {})
    for pname, pval in pars.items():
        set_par_value(node, pname, pval)

    set_flags(node, op_data.get('flags'))

    dat = op_data.get('dat_content')
    fmt = op_data.get('dat_content_format')
    if dat and hasattr(node, 'text'):
        try:
            if fmt == 'table' and isinstance(dat, list):
                for i, row in enumerate(dat):
                    for j, cell in enumerate(row):
                        if i < node.numRows and j < node.numCols:
                            node[i][j] = cell
            elif isinstance(dat, str):
                node.text = dat
        except:
            pass

    # Children
    children = op_data.get('children', [])
    for child_data in children:
        import_operator(node, child_data, depth + 1)

    return node

# \u2500\u2500 Main Import \u2500\u2500
try:
    with open('${safeFile}', 'r', encoding='utf-8') as f:
        tdn = json.load(f)

    target = op('${safeTarget}')
    if target is None:
        print(json.dumps({'success': False, 'error': 'Target path not found: ${safeTarget}'}))
    else:
        operators = tdn.get('operators', [])
        created = 0
        errors = []
        all_nodes = []
        all_connections = []
        for op_data in operators:
            try:
                node = import_operator(target, op_data)
                if node:
                    created += 1
                    all_nodes.append((node, op_data))
            except Exception as e:
                errors.append({'name': op_data.get('name', '?'), 'error': str(e)})

        # Second pass: wire connections after all operators exist
        for node, op_data in all_nodes:
            inputs = op_data.get('inputs')
            if inputs:
                set_connections(node, inputs)

        result = {
            'success': True,
            'target_path': '${safeTarget}',
            'operators_imported': created,
            'operators_total': len(operators),
            'errors': errors,
            'tdn_version': tdn.get('version', '?'),
            'tdn_network_path': tdn.get('network_path', '?'),
        }
except Exception as e:
    result = {'success': False, 'error': str(e)}

print(json.dumps(result))
`;
}
function buildDiffCode(rootPath, tdnFilePath) {
  const safePath = rootPath.replace(/'/g, "\\'");
  const safeFile = tdnFilePath.replace(/\\/g, "/").replace(/'/g, "\\'");
  return `
import json, sys

def serialize_val(val):
    if val is None:
        return None
    if isinstance(val, bool):
        return val
    if isinstance(val, (int, float)):
        return val
    if isinstance(val, str):
        return val
    if isinstance(val, (list, tuple)):
        return [serialize_val(v) for v in val]
    if isinstance(val, dict):
        return {k: serialize_val(v) for k, v in val.items()}
    return str(val)

def get_live_par(node, name):
    try:
        par = getattr(node.par, name, None)
        if par is None:
            return None
        if par.isExpression:
            return '=' + par.expr
        if par.isBind:
            return '~' + par.bindExpr
        return serialize_val(par.val)
    except:
        return None

def collect_live_ops(node, depth=0):
    ops = {}
    if node is None or depth > 50:
        return ops
    try:
        for child in node.children:
            try:
                if hasattr(child, 'OPType') and child.OPType not in ('annotatCOMP', 'commentCOMP', 'networkboxCOMP'):
                    name = child.name
                    pars = {}
                    try:
                        for par in child.pars:
                            try:
                                if par.readOnly:
                                    continue
                                val = get_live_par(child, par.name)
                                if val is not None:
                                    pars[par.name] = val
                            except:
                                pass
                    except:
                        pass

                    inputs = []
                    try:
                        for ic in child.inputConnectors:
                            try:
                                if len(ic.connections) > 0:
                                    src = ic.connections[0].owner
                                    inputs.append(src.name if src else None)
                                else:
                                    inputs.append(None)
                            except:
                                inputs.append(None)
                    except:
                        pass

                    ops[name] = {
                        'type': child.OPType if hasattr(child, 'OPType') else '?',
                        'parameters': pars,
                        'inputs': inputs,
                    }

                    try:
                        if hasattr(child, 'children') and len(child.children) > 0:
                            child_ops = collect_live_ops(child, depth=depth+1)
                            for k, v in child_ops.items():
                                ops[k] = v
                    except:
                        pass
            except:
                pass
    except:
        pass
    return ops

try:
    with open('${safeFile}', 'r', encoding='utf-8') as f:
        saved = json.load(f)
except Exception as e:
    print(json.dumps({'success': False, 'error': 'Failed to read TDN file: ' + str(e)}))
    sys.exit(0)

target = op('${safePath}')
if target is None:
    print(json.dumps({'success': False, 'error': 'Path not found: ${safePath}'}))
    sys.exit(0)

live_ops = collect_live_ops(target)

saved_ops = {}
for op_data in saved.get('operators', []):
    name = op_data.get('name', '')
    saved_ops[name] = {
        'type': op_data.get('type', '?'),
        'parameters': op_data.get('parameters', {}),
        'inputs': op_data.get('inputs', []),
    }

live_names = set(live_ops.keys())
saved_names = set(saved_ops.keys())

only_live = sorted(live_names - saved_names)
only_saved = sorted(saved_names - live_names)
shared = sorted(live_names & saved_names)

param_diffs = []
connection_diffs = []

for name in shared:
    live = live_ops[name]
    svd = saved_ops[name]

    all_pars = set(live.get('parameters', {}).keys()) | set(svd.get('parameters', {}).keys())
    for pname in sorted(all_pars):
        lv = live.get('parameters', {}).get(pname)
        sv = svd.get('parameters', {}).get(pname)
        if lv != sv:
            param_diffs.append({
                'operator': name, 'parameter': pname,
                'live_value': lv, 'saved_value': sv,
            })

    live_inputs = live.get('inputs', [])
    svd_inputs = svd.get('inputs', [])
    max_len = max(len(live_inputs), len(svd_inputs))
    for i in range(max_len):
        ls = live_inputs[i] if i < len(live_inputs) else None
        ss = svd_inputs[i] if i < len(svd_inputs) else None
        if ls != ss:
            connection_diffs.append({
                'operator': name, 'input_index': i,
                'live_source': ls, 'saved_source': ss,
            })

total = len(only_live) + len(only_saved) + len(param_diffs) + len(connection_diffs)
lines = []
if only_live:
    lines.append(f'{len(only_live)} operator(s) only in live network')
if only_saved:
    lines.append(f'{len(only_saved)} operator(s) only in saved file')
if param_diffs:
    lines.append(f'{len(param_diffs)} parameter difference(s)')
if connection_diffs:
    lines.append(f'{len(connection_diffs)} connection difference(s)')
if not lines:
    lines.append('Networks are identical')

result = {
    'success': True,
    'identical': total == 0,
    'only_live': only_live,
    'only_saved': only_saved,
    'param_diffs': param_diffs[:50],
    'connection_diffs': connection_diffs[:50],
    'total_differences': total,
    'summary': '; '.join(lines),
}
print(json.dumps(result))
`;
}
