// mcp/src/tools/classify.ts
function buildClassifyPythonCode(healthJson) {
  const escapedJson = healthJson.replace(/\\/g, "\\\\").replace(/'/g, "\\'").replace(/\$/g, "\\$");
  return `
import json, re

CATEGORY_PATTERNS = [
    ('expression_error', [r'AttributeError', r'NameError', r'SyntaxError', r'TypeError', r'not defined', r'has no attribute']),
    ('cook_loop', [r'Cook dependency loop', r'cook.*loop']),
    ('missing_file', [r'File not found', r'file not found', r'No such file', r'FileNotFoundError']),
    ('glsl_error', [r'Compile failed', r'compile.*error', r'GLSL.*error', r'shader.*error']),
]

health_json = '${escapedJson}'
health = json.loads(health_json)
issues = health.get('operators', [])

classified = []
for issue in issues:
    path = issue.get('path', '')
    err_text = (issue.get('errors', '') or '').lower()
    warn_text = (issue.get('warnings', '') or '').lower()
    text = err_text + ' ' + warn_text
    category = 'needs_manual'
    for cat, patterns in CATEGORY_PATTERNS:
        for pat in patterns:
            if re.search(pat, text, re.IGNORECASE):
                category = cat
                break
        if category != 'needs_manual':
            break
    classified.append({'path': path, 'category': category})

counts = {}
for c in classified:
    cat = c['category']
    counts[cat] = counts.get(cat, 0) + 1

print(json.dumps({'total': len(classified), 'counts': counts, 'issues': classified}))
`;
}

// mcp/src/tools/safeMode.ts
function registerSafeModeTools(server, client) {
  server.registerTool(
    "td_safe_plan",
    {
      title: "Safe Plan (Diagnose First)",
      description: "Safe mode workflow: diagnose the current TD state before making changes. Combines spatial context (*here/*this resolution) + healthcheck + error classification in a single call. Returns the resolved paths, current issues, and a recommended plan. ALWAYS call this tool BEFORE making any modifications to TD when the user uses *here, *this, or refers to their current view/selection. This prevents accidental changes to the wrong operators.",
      inputSchema: {
        path: external_exports.string().optional().describe(
          "Specific path to diagnose. If omitted, uses *here (current network) automatically."
        ),
        include_children: external_exports.boolean().optional().default(true).describe("Include child operators in healthcheck (default: true)")
      }
    },
    async ({ path: opPath, include_children }) => {
      try {
        const result = {
          steps: [],
          resolvedPaths: {},
          issues: null,
          classification: null,
          plan: null
        };
        let ctx = null;
        try {
          const spatial = await client.getSpatialContext();
          ctx = spatial?.context ?? null;
          result.steps.push({ step: "spatial_context", result: spatial });
        } catch {
          result.steps.push({
            step: "spatial_context",
            result: { error: "Could not get spatial context" }
          });
        }
        let targetPath = opPath;
        if (!targetPath && ctx?.spatialMarkers) {
          targetPath = ctx.spatialMarkers["*here"];
        }
        if (!targetPath) {
          targetPath = "/";
        }
        result.resolvedPaths = {
          target: targetPath,
          here: ctx?.spatialMarkers?.["*here"] ?? null,
          this: ctx?.spatialMarkers?.["*this"] ?? null,
          parent: ctx?.spatialMarkers?.["*parent"] ?? null,
          selected: ctx?.spatialMarkers?.["*selected"] ?? [],
          focusedOperator: ctx?.focusedOperator ?? null,
          siblings: ctx?.siblings?.length ?? 0
        };
        const health = await client.healthcheck(
          targetPath,
          include_children ?? true
        );
        result.steps.push({ step: "healthcheck", result: health });
        const hasIssues = health && !health.ok && health.issueCount > 0;
        result.issues = {
          hasIssues,
          issueCount: health?.issueCount ?? 0,
          operators: health?.operators ?? []
        };
        if (hasIssues) {
          try {
            const healthJson = JSON.stringify(health);
            const classifyCode = buildClassifyPythonCode(healthJson);
            const classifyResult = await client.execute(classifyCode, "/");
            try {
              result.classification = JSON.parse(
                classifyResult.stdout || "{}"
              );
            } catch {
              result.classification = {};
            }
          } catch {
            result.classification = {};
          }
        }
        result.plan = generateSafePlan(result);
        return ok(result);
      } catch (e) {
        return err(e);
      }
    }
  );
}
function generateSafePlan(result) {
  const plan = {
    status: "ready",
    recommendations: [],
    warnings: []
  };
  const issues = result.issues;
  const classification = result.classification;
  const paths = result.resolvedPaths;
  if (!paths.target || paths.target === "/") {
    plan.warnings.push(
      "No specific target path resolved. Consider navigating to a specific network first."
    );
  }
  if (issues?.hasIssues) {
    const counts = classification?.counts ?? {};
    const total = issues.issueCount;
    plan.status = "has_issues";
    plan.recommendations.push(
      `Found ${total} issue(s) in the network. Review before making changes.`
    );
    if (counts.expression_error) {
      plan.recommendations.push(
        `${counts.expression_error} expression error(s) detected \u2014 run td_validate with auto_fix=true to fix automatically.`
      );
    }
    if (counts.glsl_error) {
      plan.recommendations.push(
        `${counts.glsl_error} GLSL shader error(s) \u2014 check shader source code.`
      );
    }
    if (counts.cook_loop) {
      plan.warnings.push(
        `${counts.cook_loop} cook loop(s) detected \u2014 these may be pre-existing TD infrastructure issues.`
      );
    }
    if (counts.missing_file) {
      plan.recommendations.push(
        `${counts.missing_file} missing file(s) \u2014 verify file paths before proceeding.`
      );
    }
  } else {
    plan.status = "healthy";
    plan.recommendations.push(
      "Network is healthy. Safe to proceed with modifications."
    );
  }
  if (paths.selected?.length > 0) {
    plan.recommendations.push(
      `${paths.selected.length} operator(s) selected \u2014 modifications will target: ${paths.selected.join(", ")}`
    );
  }
  if (paths.focusedOperator) {
    plan.recommendations.push(
      `Current operator: ${paths.focusedOperator.path} (${paths.focusedOperator.opType})`
    );
  }
  return plan;
}

